DROP TRIGGER `documents_credit_note_cap`;
--> statement-breakpoint
CREATE TRIGGER `documents_credit_note_cap` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type IN ('credit_note', 'debit_note') AND NEW.type = 'credit_note' AND EXISTS (SELECT 1 FROM documents p, (SELECT coalesce(sum(c.total_minor), 0) AS total_minor, coalesce(sum(c.taxable_minor), 0) AS taxable_minor, coalesce(sum(c.cgst_minor), 0) AS cgst_minor, coalesce(sum(c.sgst_minor), 0) AS sgst_minor, coalesce(sum(c.igst_minor), 0) AS igst_minor, coalesce(sum(c.total_inr_minor), 0) AS total_inr_minor FROM documents c WHERE c.parent_id = NEW.parent_id AND c.type = 'credit_note' AND c.frozen_at IS NOT NULL AND c.status <> 'void' AND c.id <> NEW.id) s WHERE p.id = NEW.parent_id AND (NEW.total_minor > p.total_minor - s.total_minor OR NEW.taxable_minor > p.taxable_minor - s.taxable_minor OR NEW.cgst_minor > p.cgst_minor - s.cgst_minor OR NEW.sgst_minor > p.sgst_minor - s.sgst_minor OR NEW.igst_minor > p.igst_minor - s.igst_minor OR NEW.total_inr_minor > p.total_inr_minor - s.total_inr_minor OR (p.total_inr_minor IS NOT NULL AND NEW.total_inr_minor IS NULL))) BEGIN SELECT RAISE(ABORT, 'documents_credit_note_cap: the credit notes of an invoice cannot add up to more than the invoice, in total or in any tax head'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_ledger_identity` BEFORE UPDATE OF paid_minor, credited_minor, balance_minor, frozen_at ON `documents` WHEN NEW.frozen_at IS NOT NULL AND NEW.type IN ('proforma', 'tax_invoice', 'export_invoice', 'debit_note') AND (NEW.paid_minor IS NULL OR NEW.paid_minor < 0 OR NEW.balance_minor IS NOT max(0, NEW.total_minor - NEW.paid_minor - NEW.credited_minor)) BEGIN SELECT RAISE(ABORT, 'documents_ledger_identity: an issued document owes its total less what was paid and credited, never less than zero, and nothing paid is negative'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_discount_after_sale_from` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type IN ('credit_note', 'debit_note') AND json_extract(NEW.header_extras, '$.noteOf.reason.code') IS 'discount_after_sale' AND (NEW.issue_date IS NULL OR NEW.issue_date < '2026-11-01') BEGIN SELECT RAISE(ABORT, 'documents_discount_after_sale_from: a note for a discount after sale is dated on or after 2026-11-01'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_advance_lut_fy` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type = 'export_invoice' AND NEW.export_mode = 'lut' AND json_extract(NEW.header_extras, '$.advance.receivedOn') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM settings ts WHERE ts.key = 'tax' AND (
           EXISTS (SELECT 1 FROM json_each(ts.value, '$.luts') l WHERE json_extract(l.value, '$.fy') = (CASE WHEN CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 6, 2) AS INTEGER) >= 4 THEN substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) || printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 1) % 100) ELSE printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 99) % 100) || substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) END) AND trim(coalesce(json_extract(l.value, '$.arn'), '')) <> '')
           OR (json_extract(ts.value, '$.lut.fy') = (CASE WHEN CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 6, 2) AS INTEGER) >= 4 THEN substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) || printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 1) % 100) ELSE printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 99) % 100) || substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) END) AND trim(coalesce(json_extract(ts.value, '$.lut.arn'), '')) <> ''))) BEGIN SELECT RAISE(ABORT, 'documents_advance_lut_fy: an export invoice under LUT for a payment received needs a LUT saved for the financial year of the day the payment arrived'); END;
